/* =================== 联网搜索 =================== */
/* 角色联网搜索结果卡片：程序真实搜到的内容，由角色分享给用户，点开可看每条结果。 */
function webShareItems(raw){const map={},names={'Title':'title','URL Source':'url','Description':'desc','Date':'date'};String(raw||'').replace(/^\[(\d{1,2})\]\s*(Title|URL Source|Description|Date)\s*:\s*(.*)$/gm,(_,n,k,v)=>{(map[n]=map[n]||{})[names[k]]=String(v||'').trim();return _;});return Object.keys(map).sort((a,b)=>a-b).map(k=>map[k]).filter(x=>x.title||x.desc).map(x=>({title:String(x.title||x.desc||'').slice(0,120),url:/^https?:\/\/[^\s"'<>]+$/i.test(x.url||'')?String(x.url).slice(0,500):'',desc:String(x.desc||'').slice(0,300),date:String(x.date||'').slice(0,40)})).slice(0,8);}
function webShareHost(url){try{return new URL(url).hostname.replace(/^www\./,'');}catch(_){return'';}}
function webShareCardMsg(q,raw){q=String(q||'').trim();raw=String(raw||'').trim();if(!q||!raw||webSearchFailed(raw))return null;return{role:'assistant',type:'weblink',webShare:true,title:q.slice(0,80),snippet:raw.slice(0,1800),items:webShareItems(raw),source:(S.settings.search||{}).mode==='model'?'联网模型':'实时网页',time:Date.now(),id:uid()};}
function webShareCardHTML(m){const items=Array.isArray(m.items)?m.items:[],list=items.length?items.slice(0,2).map(it=>`<li><span>${esc(it.title)}</span>${webShareHost(it.url)?`<small>${esc(webShareHost(it.url))}</small>`:''}</li>`).join(''):`<li><span>${esc(String(m.snippet||'').replace(/\s+/g,' ').slice(0,80))}</span></li>`;return `<div class="card wx-web-card" role="button" tabindex="0" onclick="event.stopPropagation();viewWeblink('${m.id}')"><div class="wx-web-card-head">${svgIc('search',13,'currentColor')}<span>联网搜索 · ${esc(m.source||'实时网页')}</span>${items.length?`<b>${items.length} 条</b>`:''}</div><div class="wx-web-card-q">${esc(m.title)}</div><ul class="wx-web-card-list">${list}</ul><div class="wx-web-card-foot">点开查看全部结果 ›</div></div>`;}
function webShareDetailHTML(m){const items=Array.isArray(m.items)?m.items:[],body=items.length?items.map((it,i)=>{const host=webShareHost(it.url);return `<div class="wx-web-detail-item"><div class="wx-web-detail-n">${i+1}</div><div><div class="wx-web-detail-t">${esc(it.title)}</div>${it.desc?`<div class="wx-web-detail-d">${esc(it.desc)}</div>`:''}${it.url?`<a class="wx-web-detail-a" href="${esc(it.url)}" target="_blank" rel="noopener noreferrer">${esc(host||it.url)} ↗</a>`:''}${it.date?`<small>${esc(it.date)}</small>`:''}</div></div>`;}).join(''):`<div class="wx-web-detail-raw">${esc(m.snippet||'')}</div>`;return `<div class="wx-web-detail"><div class="wx-web-detail-head">${svgIc('search',15,'currentColor')}<span>联网搜索结果</span></div><h3>${esc(m.title)}</h3><div class="wx-web-detail-list">${body}</div><button class="btn g" onclick="closeModal()">关闭</button></div>`;}
function webSearchFailed(text){return /^（(?:联网|搜索)(?:失败|未启用)|^（没搜到/.test((''+(text||'')).trim());}
function localPersonalStateQuery(text){const t=(''+(text||'')).replace(/\s+/g,' ').trim();if(!t)return false;const internetExplicit=/(?:上网|联网|互联网|网页|网络)(?:查|搜)|(?:查|搜).{0,5}(?:互联网|网页|网络)/.test(t),personalState=/(?:你|你的|你自己|刚才|刚刚|有没有人|是不是有人).{0,18}(?:微信|消息|聊天|好友|手机|通讯录|短信|电话|谁找你|谁加你)|(?:微信|消息|聊天|好友|手机|通讯录|短信|电话).{0,18}(?:有人|谁|发来|找你|加你|刚才|刚刚)/.test(t);return personalState&&!internetExplicit;}
function northShopQueryRecord(c,query,result,key,request){const rows=msgs(c.id),old=rows.find(m=>m._northShopQuery&&m._northShopUserMessageId===String(key||'')&&m.shopQuery&&m.shopQuery.query===query),content=result.ok?(result.shops.length?'App内已查到：'+result.shops.map(shop=>shop.name).join('、')+'。这是店铺目录查询，尚未付款。':'App内本次查询没有匹配店铺，尚未付款。'):'App内店铺目录查询暂时失败，尚未付款。',data={account:actId(),query:String(query).slice(0,60),ok:result.ok,shops:result.shops||[],at:Date.now(),orderRequested:!!request,anchorId:String(request&&request.anchorId||key||'')};if(old){old.content=content;old.shopQuery=data;old.type='shopquery';old.role='assistant';old.from='ta';save();refreshChatMessages(c.id);return old;}const card={id:uid(),time:Date.now(),role:'assistant',from:'ta',type:'shopquery',_northShopQuery:true,_northShopUserMessageId:String(key||''),content,shopQuery:data};pushMsg(c.id,card);save();refreshChatMessages(c.id);return card;}
/* 查完店铺后的那次回复：中间插着的系统消息、一次性 5xx 都会让一些中转接口报错。失败时把中途的系统提示并成普通消息、合并相邻同角色消息，再试一次 */
function northShopFlatMessages(messages){const out=[];(messages||[]).forEach((m,i)=>{if(!m)return;const role=i>0&&m.role==='system'?'user':m.role,content=i>0&&m.role==='system'?'【系统提示】'+String(m.content||''):m.content,last=out[out.length-1];if(last&&last.role===role&&role!=='system'&&typeof last.content==='string'&&typeof content==='string')last.content+='\n\n'+content;else out.push({role,content});});if(out.length&&out[out.length-1].role==='assistant')out.push({role:'user',content:'【系统提示】请继续。'});return out;}
async function northShopPostQueryReply(messages,md,state,c){let raw;try{raw=await wechatPrimaryReply(messages,md,state,c);}catch(e){if(e&&e.name==='AbortError'||/abort/i.test(String(e&&e.message)))throw e;raw=await wechatPrimaryReply(northShopFlatMessages(messages),md,state,c);}let content=md.unfilteredOutput?modelUnfilteredText(raw):roleVisibleEnvelopeText(raw),usable=value=>!!String(value||'').replace(/[\[【]\s*(?:内心|心情|情绪|事件簿)\s*[|｜:：][^\]】]*[\]】]/g,'').replace(/\[查店铺\|[^\]]*\]/g,'').replace(/[\[【]\s*(?:保持安静|不说话)\s*[\]】]/g,'').trim();if(!usable(content)&&!state.fallback&&wechatAuxConfigured(md.routeIndex)){state.fallback=true;raw=await chatAPI(messages,Object.assign({},md,{aux:true}));content=md.unfilteredOutput?modelUnfilteredText(raw):roleVisibleEnvelopeText(raw);}if(!usable(content)){const error=new Error('查询后的模型没有返回可执行回复');error.code='north-shop-empty-reply';throw error;}return content;}
function autoWebQuery(){return ''; }
/* SEARCH_MODEL_FALLBACK_V1：jina 是国外网站，手机网络连不上时角色联网就失败（她 10-31 遇到过超时）。
   现在 jina 连不上或报错时，自动用聊天模型查一次；结果前面注明「jina 连不上，以下由聊天模型回答，可能不是最新」，不冒充实时网页。
   没配聊天模型、或模型也失败，就照旧报原来的失败。 */
async function webSearchModelFallback(q){const a=S.settings&&S.settings.chat||{},base=String(a.base||'').replace(/\/+$/,''),key=a.key,model=a.model;if(!base||!key||!model)return'';try{const r=await fetchT(base+'/chat/completions',{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+key},body:JSON.stringify({model,max_tokens:700,messages:[{role:'system',content:'你是联网搜索助手。请就用户的问题给出尽量最新、真实的信息；如果你具备联网/检索能力就联网查证。无法真实检索时必须明确说无法联网，不得凭记忆伪装实时结果。'},{role:'user',content:'联网搜索并简要回答：'+q}]})},45000);if(!r.ok)return'';const d=await r.json().catch(()=>null),t=String(d&&d.choices&&d.choices[0]&&d.choices[0].message&&d.choices[0].message.content||'').trim();return t?('（jina 连不上，以下由聊天模型回答，可能不是最新）'+t).slice(0,1800):'';}catch(_){return'';}}
async function webSearch(q){const ws=S.settings.search||{};
  if(ws.mode==='model'){const a=S.settings.chat;const base=(ws.base||a.base||'').replace(/\/+$/,'');const key=ws.key||a.key;const model=ws.model||a.model;
    try{const r=await fetchT(base+'/chat/completions',{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+key},body:JSON.stringify({model,max_tokens:700,messages:[{role:'system',content:'你是联网搜索助手。请就用户的问题给出尽量最新、真实的信息；如果你具备联网/检索能力就联网查证。无法真实检索时必须明确说无法联网，不得凭记忆伪装实时结果。'},{role:'user',content:'联网搜索并简要回答：'+q}]})});
      const d=await r.json().catch(()=>null);if(!r.ok)return '（搜索失败 '+r.status+'：检查设置里的联网模型）';
      return ((d&&d.choices&&d.choices[0]&&d.choices[0].message&&d.choices[0].message.content)||'').slice(0,1800)||'（没搜到内容）';}catch(e){return '（搜索失败，检查联网模型设置）';}}
  const base=(ws.base||'https://s.jina.ai').replace(/\/+$/,'');
  try{const h={'Accept':'text/plain','X-Respond-With':'no-content'};if(ws.key)h['Authorization']='Bearer '+ws.key;
    const r=await fetchT(base+'/'+encodeURIComponent(q),{headers:h});const t=await r.text();
    if(!r.ok){const fb=await webSearchModelFallback(q);if(fb)return fb;return '（联网失败 '+r.status+'：可能要去"设置→联网搜索"填上 jina 密钥，或改用「用模型」）';}
    return (t||'').slice(0,1800);}catch(e){const fb=await webSearchModelFallback(q);if(fb)return fb;return '（联网失败，检查网络，或在"设置→联网搜索"换方式）';}}
/* =================== 浏览器 =================== */
let _brBusy=false,_brBusyMode='';
function renderBrowser(inspection){const b=inspection?{history:spyBrowserRows(inspection)}:S.browser||{},sim='hisWxSimulatedButton()';
  const webOn=!!(S.settings.web&&S.settings.web.enabled),items=b.items||[],history=(b.history||[]).slice(0,6),src=b.lastSearchMode==='web'?'已连接实时网络':b.lastSearchMode==='webmodel'?'联网模型结果':b.lastSearchMode==='fallback'?'网络不可用，已切换智能回答':b.lastSearchMode==='model'?'智能回答 · 内容可能不是最新':'';
  const search=`<div class="br-search"><span>${svgIc('search',19,'#8a8d94')}</span><input id="br_q" value="${esc(b.q||'')}" placeholder="搜索你感兴趣的内容" onkeydown="if(event.key==='Enter')${inspection?sim:'browserSearch()'}"${inspection?` readonly onclick="${sim}"`:''}><button onclick="${inspection?sim:`browserSearch()`}" ${!inspection&&_brBusy?'disabled':''}>${!inspection&&_brBusy?'搜索中':'百度一下'}</button></div>`;
  const homeView=`<div class="br-home"><div class="br-logo">百<span>度</span></div>${search}<div class="br-shortcuts"><button onclick="${inspection?sim:`browserSearch('今日热点')`}">${svgIc('star',21,'#ff5a54')}<span>热榜</span></button><button onclick="${inspection?sim:`browserSearch('今日新闻')`}">${svgIc('notebook',21,'#3478f6')}<span>资讯</span></button><button onclick="${inspection?sim:`browserSearch('热门图片')`}">${svgIc('image',21,'#8f63e9')}<span>图片</span></button><button onclick="${inspection?sim:`browserSearch('生活实用技巧')`}">${svgIc('book',21,'#f4a51c')}<span>知道</span></button></div><section class="br-hot"><div class="br-section-title"><b>百度热搜</b><small>实时热点</small></div>${['今日有哪些值得关注的消息','近期热门影视作品','本地周末好去处','夏日生活实用指南','大家都在听的新歌'].map((x,i)=>`<button onclick="${inspection?sim:`browserSearch('${x}')`}"><i>${i+1}</i><span>${x}</span><em>${i<2?'热':''}</em></button>`).join('')}</section>${history.length?`<section class="br-recent"><div class="br-section-title"><b>最近搜索</b><button onclick="${inspection?sim:'brHistory()'}">全部记录</button></div><div>${history.map((x,i)=>`<button onclick="${inspection?sim:`brRe(${i})`}">${svgIc('clock',13,'#9699a0')} ${esc(x.q)}</button>`).join('')}</div></section>`:''}<div class="br-network">${webOn?'联网搜索已开启':'当前使用智能回答，可在设置中开启联网搜索'}</div></div>`;
  const busyView=`<div class="br-results"><div class="br-result-search">${search}</div><div class="br-loading"><i></i><i></i><i></i><span>${_brBusyMode==='model'?'正在整理答案':'正在检索相关内容'}</span></div></div>`;
  const resultView=`<div class="br-results"><div class="br-result-search">${search}</div><div class="br-result-meta"><span>搜索结果 · ${items.length}</span><small>${src}</small></div>${items.map((it,i)=>`<article class="br-result" onclick="${inspection?sim:`brView(${i})`}"><div class="br-site"><span>B</span><div>百度智能搜索<small>baidu.com</small></div></div><h3>${esc(it.title)}</h3><p>${esc((it.snippet||'').slice(0,220))}${(it.snippet||'').length>220?'…':''}</p><div class="br-actions"><button onclick="${inspection?sim:`event.stopPropagation();brView(${i})`}">查看详情</button><button onclick="${inspection?sim:`event.stopPropagation();brFwd(${i})`}">转发给角色</button></div></article>`).join('')}<div class="br-end">没有更多结果了</div></div>`;
  return `<div class="nav br-nav"><span class="l" onclick="${inspection?`spyOpen('${inspection}','')`:'home()'}">‹</span><span class="t">百度</span><span class="r" onclick="${inspection?`spyBrowserHistory('${inspection}')`:'brHistory()'}">${svgIc('clock',19,'currentColor')}</span></div><div class="scroll br-page">${!inspection&&_brBusy?busyView:(items.length?resultView:homeView)}</div>`;}
async function browserModelSearch(q){return await chatAPI([{role:'system',content:'你是浏览器里的普通回答模型。当前没有可用的真实联网结果，只能依据已有知识回答，可能不是最新信息。整理成3到5条简短结果，每行一条，严格格式：标题:::一两句话摘要。不要声称刚刚搜索、查到实时网页或看到最新资料。'},{role:'user',content:q}],{max:700,aux:true});}
async function browserSearch(qArg){if(_brBusy)return;const q=(qArg||($('#br_q')?$('#br_q').value:'')||'').trim();if(!q){toast('搜点啥呢');return;}
  S.browser=S.browser||{};S.browser.q=q;S.browser.history=S.browser.history||[];S.browser.history.unshift({q,time:Date.now()});S.browser.history=S.browser.history.slice(0,40);
  const webOn=!!(S.settings.web&&S.settings.web.enabled),webMode=((S.settings.search||{}).mode||'jina')==='model'?'webmodel':'web';_brBusy=true;_brBusyMode=webOn?webMode:'model';save();render();
  try{let r='',mode='model';if(webOn){const raw=await webSearch(q);if(webSearchFailed(raw)){mode='fallback';toast('⚠️ 联网失败，已改用普通模型');r=await browserModelSearch(q);}else{mode=webMode;toast(mode==='web'?'🌐 已获取 Jina 真实联网结果':'🌐 已获得联网模型回答');r=await chatAPI([{role:'system',content:'你是浏览器搜索结果整理器。根据下面联网搜到的资料，整理成3到5条搜索结果，要准确、基于资料、不要编造。每行一条，严格格式：标题:::一两句话摘要。只输出这些行。'},{role:'user',content:'搜索词：'+q+'\n\n联网资料：\n'+(raw||'').slice(0,1500)}],{max:700,aux:true});}}else{r=await browserModelSearch(q);}
    const items=looseLines(r).map(p=>({title:clean(p[0]),snippet:(p[1]||p[0]||'').trim()})).filter(x=>x.title);
    S.browser.items=items.length?items:[{title:q,snippet:mode==='web'?'没有整理出相关联网结果':'模型没有生成可用回答'}];S.browser.lastSearchMode=mode;
  }catch(e){S.browser.items=[{title:q,snippet:'搜索失败了，检查下网络再试一次'}];S.browser.lastSearchMode=webOn?'fallback':'model';}
  _brBusy=false;_brBusyMode='';save();render();}
function brView(i){const it=(S.browser.items||[])[i];if(!it)return;
  openModal(`<h3 style="color:#7db3ff">${esc(it.title)}</h3><div style="max-height:55vh;overflow:auto;color:#ddd;line-height:1.8;white-space:pre-wrap;font-size:14px">${esc(it.snippet)}</div><div class="btns" style="margin-top:12px"><button class="btn g" onclick="closeModal()">关闭</button><button class="btn p" onclick="closeModal();brFwd(${i})">转发给角色</button></div>`);}
function brFwd(i){const it=(S.browser.items||[])[i];if(!it)return;const cs=S.contacts.filter(c=>!c.deleted&&(isMain()||addedHere(c)));if(!cs.length){toast('先加个角色');return;}
  window._brF=it;openModal(`<h3>转发给</h3>${cs.map(c=>`<div class="section"><div class="it" onclick="doBrFwd('${c.id}')">${esc(c.remark||c.name)}<span class="v">›</span></div></div>`).join('')}<button class="btn g" style="margin-top:8px" onclick="closeModal()">取消</button>`);}
function doBrFwd(cid){const it=window._brF;if(!it)return;pushMsg(cid,{role:'user',type:'weblink',title:it.title,snippet:it.snippet,q:(S.browser&&S.browser.q)||'',id:uid()});closeModal();toast('已转发给角色');scheduleReply(cid);}
function spyBrowserRows(id){return ((S.spy&&S.spy[id]&&S.spy[id].browser)||[]).map(x=>typeof x==='string'?{q:x}:Object.assign({},x,{q:x.q||x.query||x.title||x.item||x.text||'',time:x.time||x.ts||0}));}
function spyBrowserHistory(id){openModal(browserHistoryHTML(spyBrowserRows(id),true));}
function browserHistoryHTML(h,inspection){return `<h3>搜索记录</h3>${h.length?h.map((x,i)=>`<div class="it"><span onclick="${inspection?'hisWxSimulatedButton()':`brRe(${i})`}" style="flex:1;color:#ccc;cursor:pointer;display:flex;align-items:center;gap:8px">${svgIc('search',15,'#888')}${esc(x.q)}</span><small style="color:#777">${x.time?fmtDate(x.time):''}</small></div>`).join(''):'<div class="empty">还没搜过</div>'}<div class="btns" style="margin-top:8px"><button class="btn d" onclick="${inspection?'hisWxSimulatedButton()':'brClearHist()'}">清空记录</button><button class="btn g" onclick="closeModal()">关闭</button></div>`;}
function brHistory(){openModal(browserHistoryHTML((S.browser&&S.browser.history)||[],false));}
async function brClearHist(){if(!await uiConfirm('清空全部浏览/搜索记录？\n（搜索框、搜索结果、历史记录都会清掉）'))return;S.browser={q:'',items:[],history:[]};save();closeModal();if(cur().p==='browser'||cur().p==='spy')render();toast('已清空');}
function brRe(i){const x=(S.browser&&S.browser.history||[])[i];if(!x)return;closeModal();browserSearch(x.q);}
function viewWeblink(mid){let m;for(const k in S.messages){const x=S.messages[k].find(y=>y.id===mid);if(x){m=x;break;}}if(!m)return;
  if(m.webShare){openModal(webShareDetailHTML(m));return;}
  openModal(`<h3 style="color:#7db3ff">${esc(m.title)}</h3><div style="max-height:55vh;overflow:auto;color:#ddd;line-height:1.8;white-space:pre-wrap;font-size:14px">${esc(m.snippet||'')}</div><button class="btn g" style="margin-top:12px" onclick="closeModal()">关闭</button>`);}

/* =================== 闹钟 =================== */
let _nativeAlarmAuthorized=false,_nativeAlarmSyncBusy=false,_nativeAlarmSyncAgain=false;
