async function momentRunRoleExchange(p){if(!p||p._roleExchangeDone)return;p._roleExchangeDone=true;p._roleExchangeCount=Math.min(2,Math.max(0,+p._roleExchangeCount||0));const sources=(p.comments||[]).filter(cm=>cm&&cm.cid&&cm.cid!=='me').slice(-6),pool=S.contacts.filter(c=>!c.deleted&&!c.blocked&&momentVisibleTo(p,c.id));let attempts=0;
  for(const source of sources){if(p._roleExchangeCount>=2||attempts>=4)break;const candidates=pool.filter(c=>c.id!==source.cid&&!(p.comments||[]).some(cm=>cm&&cm.replyToId===source.id&&cm.cid===c.id));for(const c of candidates.slice(0,2)){if(p._roleExchangeCount>=2||attempts++>=4)break;try{const prompt='你刚在朋友圈看到'+source.name+'评论了'+S.me.name+'的动态。动态正文："'+cleanMomentText(p.text).slice(0,500)+'"。'+source.name+'的评论："'+source.text+'"。只有你确实在意、想接话时，才回复“@'+source.name+' 一句自然短回复”；否则只回复“忽略”。不能替别人说话。';const raw=cleanReply(await chatAPI([{role:'system',content:buildSystem(c)},{role:'user',content:prompt}],{routeIndex:roleChatRouteIndex(c),aux:c.model==='aux',complete:true}));if(!raw||/^(忽略|不回应|无|路过)$/.test(raw))continue;const text=raw.replace(new RegExp('^[@＠]'+String(source.name||'').replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'[：:\\s]*'),'').trim();if(!text||momentRoleCommentRepeated(text,p.comments))continue;p._roleExchangeCount=Math.min(2,p._roleExchangeCount+1);p.comments.push({id:uid(),name:c.remark||c.name,cid:c.id,text:text.slice(0,60),time:Date.now(),replyToId:source.id||'',replyToName:source.name||'',replyRound:p._roleExchangeCount});save();break;}catch(_){}}
  }
}
async function reactToMyMoment(p){const pool=S.contacts.filter(c=>!c.deleted&&!c.blocked&&momentVisibleTo(p,c.id)),lovers=pool.filter(momentContactIsLover),reminded=pool.filter(c=>(p.remind||[]).includes(c.id)&&!lovers.includes(c)),others=pool.filter(c=>!momentContactIsLover(c)&&!reminded.includes(c)).slice(0,Math.max(0,3-lovers.length-reminded.length)),selected=[...lovers,...reminded,...others];
  p.likes=Array.isArray(p.likes)?p.likes:[];p.comments=Array.isArray(p.comments)?p.comments:[];
  for(const c of selected){const lover=momentContactIsLover(c);if(lover){momentEnsureRoleLike(p,c);save();}try{const out=await momentRequestRoleReaction(p,c,lover);if(out.like)momentEnsureRoleLike(p,c);if(out.comment&&!momentRoleCommentRepeated(out.comment,p.comments)){p.comments.push({id:uid(),name:c.remark||c.name,cid:c.id,text:out.comment.slice(0,60),time:Date.now(),requiredLoverComment:lover});if(lover&&p._loverCommentFailures)delete p._loverCommentFailures[c.id];}else if(lover){p._loverCommentFailures=p._loverCommentFailures||{};p._loverCommentFailures[c.id]={at:Date.now(),reason:'本次模型没有返回真实评论'};}save();const page=cur();if(page.p==='wxmoment'||page.p==='wechat'&&wxTab==='moments'||page.p==='roleMomentDetail')momentRenderKeepScroll(p.id);}catch(e){if(lover){p._loverCommentFailures=p._loverCommentFailures||{};p._loverCommentFailures[c.id]={at:Date.now(),reason:String(e&&e.message||'评论请求失败').slice(0,120)};save();}}}
  await momentRunRoleExchange(p);save();const page=cur();if(page.p==='wxmoment'||page.p==='wechat'&&wxTab==='moments'||page.p==='roleMomentDetail')momentRenderKeepScroll(p.id);
}
const _momentRequiredReactionBusy=new Set();
async function momentRetryRequiredReactions(pid){const p=(S.moments||[]).find(x=>x&&x.id===pid),failures=p&&p._loverCommentFailures;if(!p||!failures||_momentRequiredReactionBusy.has(pid))return;_momentRequiredReactionBusy.add(pid);try{for(const cid of Object.keys(failures)){const c=getC(cid);if(!c||c.deleted||c.blocked||!momentContactIsLover(c)||!momentVisibleTo(p,c.id)){delete failures[cid];continue;}momentEnsureRoleLike(p,c);try{const out=await momentRequestRoleReaction(p,c,true);if(out.comment&&!momentRoleCommentRepeated(out.comment,p.comments)){p.comments.push({id:uid(),name:c.remark||c.name,cid:c.id,text:out.comment.slice(0,60),time:Date.now(),requiredLoverComment:true});delete failures[cid];}else failures[cid]={at:Date.now(),reason:'本次模型没有返回真实评论'};}catch(e){failures[cid]={at:Date.now(),reason:String(e&&e.message||'评论请求失败').slice(0,120)};}save();momentRenderKeepScroll(p.id);}if(!Object.keys(failures).length)delete p._loverCommentFailures;save();}finally{_momentRequiredReactionBusy.delete(pid);}}
function momentRequiredReactionStatusHTML(p){const count=Object.keys(p&&p._loverCommentFailures||{}).length;return count?`<button class="moment-role-retry" onclick="event.stopPropagation();momentRetryRequiredReactions(${jq(p.id)})">情侣评论未完成 · 点此重试</button>`:'';}
